154→  public static AutomergeDocument Load(byte[] data)
155→  {
156→    if(data is null)
157→    {
158→      throw new ArgumentNullException(nameof(data));
159→    }
160→
161→    if(data.Length == 0)
162→    {
163→      throw new ArgumentException("Cannot load empty data.", nameof(data));
164→    }
165→
166→    try
167→    {
168→      using var slice = Native.SliceU8.From(data);
169→      var doc = Native.AutomergeDoc.Load(slice);
170→      return new AutomergeDocument(doc);
171→    }
172→    catch(Exception ex) when(ex.GetType().Name.StartsWith("EnumException") || ex.GetType().Name == "InteropException")
173→    {
174→      // Convert EnumException/InteropException from AsOk() to proper AutomergeException
175→      throw new AutomergeException(
176→        Native.AutomergeFfiErrorCode.AutomergeError,
177→        "Failed to load Automerge document. The data may be invalid or corrupted.",
178→        ex);
179→    }
180→  }
