  5→/// <summary>
  6→/// Integration test: full rich text workflow with blocks, marks, and sync.
  7→/// </summary>
  8→[Trait("Category", "BlocksIntegration")]
  9→public sealed class AutomergeBlockIntegrationTests
 10→{
 11→  [Fact]
 12→  public void FullRichTextWorkflow_CreateBlocksMarksSync_SpansIdenticalAfterSync()
 13→  {
 14→    // ── Step 1: Create document with rich text structure ──────────
 15→    using var doc1 = AutomergeDocument.Create();
 16→    var root = doc1.RootId;
 17→
 18→    // Create a text object
 19→    var textId = doc1.PutObject(root, "content", AutomergeContainerType.Text);
 20→
 21→    // Write initial text
 22→    doc1.SpliceText(textId, 0, 0, "IntroductionThis is the first paragraph.This is the second paragraph.");
 23→
 24→    // ── Step 2: Add block markers ────────────────────────────────
 25→    // Insert heading block at position 0 (before "Introduction")
 26→    var headingBlock = doc1.SplitBlock(textId, 0);
 27→    doc1.PutString(headingBlock, "type", "heading");
 28→
 29→    // Insert paragraph block before "This is the first..."
 30→    // After split at 0, "Introduction" is at offset 1-12, then text continues
 31→    // The text after "Introduction" starts at index 13 (12 chars + 1 block marker)
 32→    var para1Block = doc1.SplitBlock(textId, 13);
 33→    doc1.PutString(para1Block, "type", "paragraph");
 34→
 35→    // Insert paragraph block before "This is the second..."
 36→    // After two splits, we need to account for block markers
 37→    // "Introduction" (12) + block(1) + "This is the first paragraph." (29) + block(1) = index 43
 38→    var para2Block = doc1.SplitBlock(textId, 43);
 39→    doc1.PutString(para2Block, "type", "paragraph");
 40→
 41→    // ── Step 3: Apply marks ──────────────────────────────────────
 42→    // Bold "Introduction" (after the heading block marker at 0, text at 1..12)
 43→    doc1.Mark(textId, 1, 13, "bold", true);
 44→
 45→    // Italic "first" in "This is the first paragraph."
 46→    // After heading block at 0, "Introduction" at 1-12, para1 block at 13, "This is the " at 14-25, "first" at 26-30
 47→    doc1.Mark(textId, 26, 31, "italic", true);
 48→
 49→    doc1.Commit("full rich text structure");
 50→
 51→    // ── Step 4: Read spans from doc1 ─────────────────────────────
 52→    var spans1 = doc1.GetSpans(textId);
 53→
 54→    // Verify we have block spans
 55→    var blockSpans1 = spans1.OfType<AutomergeBlockSpan>().ToList();
 56→    Assert.True(blockSpans1.Count >= 3, $"Expected at least 3 block spans, got {blockSpans1.Count}");
 57→
 58→    // Verify we have text spans with marks
 59→    var textSpans1 = spans1.OfType<AutomergeTextSpan>().ToList();
 60→    Assert.NotEmpty(textSpans1);
 61→
 62→    // Verify marks exist
 63→    var allMarks1 = textSpans1.SelectMany(s => s.Marks).ToList();
 64→    Assert.Contains(allMarks1, m => m.Name == "bold");
 65→    Assert.Contains(allMarks1, m => m.Name == "italic");
 66→
 67→    // ── Step 5: Sync to doc2 via sync protocol ───────────────────
 68→    using var doc2 = AutomergeDocument.Create();
 69→    using var sync1to2 = doc1.CreateSyncState();
 70→    using var sync2to1 = doc2.CreateSyncState();
 71→
 72→    for(var i = 0; i < 10; i++)
 73→    {
 74→      var msg1 = doc1.GenerateSyncMessage(sync1to2);
 75→      var msg2 = doc2.GenerateSyncMessage(sync2to1);
 76→      if(msg1 == null && msg2 == null)
 77→        break;
 78→      if(msg1 != null)
 79→        doc2.ReceiveSyncMessage(sync2to1, msg1);
 80→      if(msg2 != null)
 81→        doc1.ReceiveSyncMessage(sync1to2, msg2);
 82→    }
 83→
 84→    // ── Step 6: Verify spans are identical after sync ────────────
 85→    var spans2 = doc2.GetSpans(textId);
 86→
 87→    Assert.Equal(spans1.Count, spans2.Count);
 88→
 89→    for(var i = 0; i < spans1.Count; i++)
 90→    {
 91→      Assert.Equal(spans1[i].GetType(), spans2[i].GetType());
 92→
 93→      if(spans1[i] is AutomergeTextSpan t1 && spans2[i] is AutomergeTextSpan t2)
 94→      {
 95→        Assert.Equal(t1.Text, t2.Text);
 96→        Assert.Equal(t1.Marks.Count, t2.Marks.Count);
 97→
 98→        for(var m = 0; m < t1.Marks.Count; m++)
 99→        {
100→          Assert.Equal(t1.Marks[m].Name, t2.Marks[m].Name);
101→          Assert.Equal(t1.Marks[m].Value.Kind, t2.Marks[m].Value.Kind);
102→        }
103→      }
104→
