  5→/// <summary>
  6→/// End-to-end integration tests for rich text: create doc → insert text → add block
  7→/// markers → apply marks (bold, italic, links) → splice within marked regions → sync
  8→/// to second doc → verify spans match exactly.
  9→/// </summary>
 10→[Trait("Category", "RichTextIntegration")]
 11→public sealed class AutomergeRichTextIntegrationTests
 12→{
 13→  // ── Full Pipeline: Text + Blocks + Marks + Splice + Sync ──────────
 14→
 15→  [Fact]
 16→  public void RichText_FullPipeline_TextBlocksMarksAndSync()
 17→  {
 18→    // ARRANGE: Create document with text
 19→    using var doc = AutomergeDocument.Create();
 20→    var root = doc.RootId;
 21→
 22→    var textId = doc.PutObject(root, "content", AutomergeContainerType.Text);
 23→    doc.SpliceText(textId, 0, 0, "Hello World. This is paragraph one.");
 24→    doc.Commit("insert text");
 25→
 26→    // ACT: Add a block marker to split into paragraphs
 27→    var blockId = doc.SplitBlock(textId, 13); // Split at "This is..."
 28→    doc.Commit("split block");
 29→
 30→    // Apply bold to "Hello" (chars 0-5)
 31→    doc.Mark(textId, 0, 5, "bold", true);
 32→    doc.Commit("mark bold");
 33→
 34→    // Apply italic to "World" (chars 6-11)
 35→    doc.Mark(textId, 6, 11, "italic", true);
 36→    doc.Commit("mark italic");
 37→
 38→    // Apply a link mark to "paragraph one" (chars 22-35 in the original text,
 39→    // but after block split the block marker takes up 1 char at index 13,
 40→    // so "paragraph one" starts later)
 41→    // Let's read the text to find the correct positions
 42→    var text = doc.GetText(textId);
 43→    var paraOneStart = text.IndexOf("paragraph one");
 44→    if(paraOneStart >= 0)
 45→    {
 46→      doc.Mark(textId, (ulong)paraOneStart, (ulong)(paraOneStart + 13), "link", "https://example.com");
 47→      doc.Commit("mark link");
 48→    }
 49→
 50→    // Splice text within the bold region: insert "Beautiful " before "World"
 51→    doc.SpliceText(textId, 6, 0, "Beautiful ");
 52→    doc.Commit("splice within marked region");
 53→
 54→    // ASSERT: Verify marks survive splice
 55→    var marks = doc.GetMarks(textId);
 56→    Assert.NotEmpty(marks);
 57→
 58→    var boldMark = marks.FirstOrDefault(m => m.Name == "bold");
 59→    Assert.NotNull(boldMark);
 60→    Assert.Equal(0UL, boldMark.Start);
 61→    // Bold should still cover "Hello" (0..5)
 62→    Assert.Equal(5UL, boldMark.End);
 63→
 64→    var italicMark = marks.FirstOrDefault(m => m.Name == "italic");
 65→    Assert.NotNull(italicMark);
 66→    // Italic should have shifted right by 10 chars ("Beautiful ")
 67→    // Original was 6..11, now 16..21
 68→    Assert.Equal(16UL, italicMark.Start);
 69→    Assert.Equal(21UL, italicMark.End);
 70→
 71→    // Verify text content
 72→    var finalText = doc.GetText(textId);
 73→    Assert.Contains("Hello", finalText);
 74→    Assert.Contains("Beautiful", finalText);
 75→    Assert.Contains("World", finalText);
 76→
 77→    // SYNC: Sync to a second document
 78→    using var doc2 = AutomergeDocument.Create();
 79→    using var syncAB = doc.CreateSyncState();
 80→    using var syncBA = doc2.CreateSyncState();
 81→
 82→    for(var i = 0; i < 10; i++)
 83→    {
 84→      var msgA = doc.GenerateSyncMessage(syncAB);
 85→      var msgB = doc2.GenerateSyncMessage(syncBA);
 86→      if(msgA is null && msgB is null) break;
 87→      if(msgA is not null) doc2.ReceiveSyncMessage(syncBA, msgA);
 88→      if(msgB is not null) doc.ReceiveSyncMessage(syncAB, msgB);
 89→    }
 90→
 91→    // Verify the synced document has identical text
 92→    var text2 = doc2.GetText(textId);
 93→    Assert.Equal(finalText, text2);
 94→
 95→    // Verify marks match on synced document
 96→    var marks2 = doc2.GetMarks(textId);
 97→    Assert.Equal(marks.Count, marks2.Count);
 98→
 99→    foreach(var originalMark in marks)
100→    {
101→      var syncedMark = marks2.FirstOrDefault(m => m.Name == originalMark.Name);
102→      Assert.NotNull(syncedMark);
103→      Assert.Equal(originalMark.Start, syncedMark.Start);
104→      Assert.Equal(originalMark.End, syncedMark.End);
105→      Assert.Equal(originalMark.Value.Kind, syncedMark.Value.Kind);
106→    }
107→
108→    // Verify spans match exactly between the two documents
109→    var spans1 = doc.GetSpans(textId);
110→    var spans2 = doc2.GetSpans(textId);
111→    Assert.Equal(spans1.Count, spans2.Count);
112→
113→    for(var i = 0; i < spans1.Count; i++)
114→    {
115→      Assert.Equal(spans1[i].GetType(), spans2[i].GetType());
116→      if(spans1[i] is AutomergeTextSpan ts1 && spans2[i] is AutomergeTextSpan ts2)
117→      {
118→        Assert.Equal(ts1.Text, ts2.Text);
119→        Assert.Equal(ts1.Marks.Count, ts2.Marks.Count);
120→      }
121→    }
122→  }
