  5→/// <summary>
  6→/// Tests for cursor persistence: create cursor → save → load → resolve cursor →
  7→/// verify position is correct after concurrent edits by a third party.
  8→/// </summary>
  9→[Trait("Category", "CursorPersistence")]
 10→public sealed class AutomergeCursorPersistenceTests
 11→{
 12→  // ── Cursor Survives Save/Load Cycle ────────────────────────────────
 13→
 14→  [Fact]
 15→  public void Cursor_SurvivesSaveLoadCycle_ShouldResolveCorrectly()
 16→  {
 17→    // ARRANGE: Create document with a list
 18→    using var doc = AutomergeDocument.Create();
 19→    var root = doc.RootId;
 20→
 21→    var list = doc.PutObject(root, "items", AutomergeContainerType.List);
 22→    doc.ListInsertString(list, 0, "alpha");
 23→    doc.ListInsertString(list, 1, "beta");
 24→    doc.ListInsertString(list, 2, "gamma");
 25→    doc.ListInsertString(list, 3, "delta");
 26→    doc.Commit("init list");
 27→
 28→    // Create cursor pointing at "beta" (index 1)
 29→    var cursor = doc.GetCursor(list, 1);
 30→    byte[] cursorBytes = cursor.ToBytes();
 31→
 32→    // Save the document
 33→    byte[] saved = doc.Save();
 34→
 35→    // ACT: Load in a new document and resolve the cursor
 36→    using var loaded = AutomergeDocument.Load(saved);
 37→    var restoredCursor = AutomergeCursor.FromBytes(cursorBytes);
 38→    var position = loaded.GetCursorPosition(list, restoredCursor);
 39→
 40→    // ASSERT: Cursor should still point to index 1 ("beta")
 41→    Assert.Equal(1UL, position);
 42→    Assert.Equal("beta", loaded.ListGetString(list, position));
 43→  }
