 45→  // ── Cursor Survives Save/Load + Concurrent Insert by Third Party ──
 46→
 47→  [Fact]
 48→  public void Cursor_SurvivesSaveLoadAndConcurrentInsert_ShouldTrackElement()
 49→  {
 50→    // ARRANGE: Create doc with text
 51→    using var doc1 = AutomergeDocument.Create();
 52→    var root = doc1.RootId;
 53→
 54→    var textId = doc1.PutObject(root, "content", AutomergeContainerType.Text);
 55→    doc1.SpliceText(textId, 0, 0, "Hello World");
 56→    doc1.Commit("init text");
 57→
 58→    // Create cursor at position 6 (the "W" in "World")
 59→    var cursor = doc1.GetCursor(textId, 6);
 60→    byte[] cursorBytes = cursor.ToBytes();
 61→
 62→    // Save and create a third-party document (simulates another peer)
 63→    byte[] saved = doc1.Save();
 64→    using var doc3 = AutomergeDocument.Load(saved);
 65→
 66→    // Third party inserts text BEFORE the cursor position
 67→    doc3.SpliceText(textId, 0, 0, "Hey! ");
 68→    doc3.Commit("third party insert before");
 69→
 70→    // ACT: Load the original doc and merge the third party changes
 71→    using var docLoaded = AutomergeDocument.Load(saved);
 72→    docLoaded.Merge(doc3);
 73→
 74→    // Resolve cursor in the merged document
 75→    var restoredCursor = AutomergeCursor.FromBytes(cursorBytes);
 76→    var position = docLoaded.GetCursorPosition(textId, restoredCursor);
 77→
 78→    // ASSERT: "World" has shifted right by 5 chars ("Hey! ")
 79→    // The cursor should now point to position 11 (6 + 5)
 80→    var text = docLoaded.GetText(textId);
 81→    Assert.Equal("Hey! Hello World", text);
 82→    Assert.Equal(11UL, position);
 83→
 84→    // The character at the cursor position should be 'W' from "World"
 85→    Assert.Equal('W', text[(int)position]);
 86→  }
