 118→  public Repo(RepoConfig config)
 119→  {
 120→    if(config is null)
 121→      throw new ArgumentNullException(nameof(config));
 122→
 123→    // Initialize identity
 124→    _peerId = config.PeerId ?? PeerId.Generate();
 125→    _isEphemeral = config.IsEphemeral;
 126→    _saveDebounceRate = config.SaveDebounceRate;
 127→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 128→    _idFactory = config.IdFactory;
 129→
 130→    // Initialize storage subsystem
 131→    if(config.Storage is not null)
 132→    {
 133→      _storage = new StorageSubsystem(config.Storage);
 134→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 135→      _storage.DocumentSaved += OnStorageDocumentSaved;
 136→    }
 137→
 138→    // Initialize network subsystem
 139→    _network = new NetworkSubsystem(config.NetworkAdapters);
 140→    _network.PeerCandidate += OnNetworkPeerCandidate;
 141→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 142→    _network.MessageReceived += OnNetworkMessageReceived;
 143→
 144→    // Initialize synchronizer
 145→    _synchronizer = new CollectionSynchronizer(
 146→      GetDocument,
 147→      UpdateDocument,
 148→      GetPeerMetadata,
 149→      RequestDocument,
 150→      config.Denylist);
 151→
 152→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 153→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 154→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 155→
 156→    // Set share and access policies
 157→    if(_shareConfig.Announce is not null)
 158→    {
 159→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 160→    }
 161→
 162→    if(_shareConfig.Access is not null)
 163→    {
 164→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 165→    }
 166→  }
