398→  public DocLocalChange<T>? Change(
399→    Action<AutomergeDocument> mutation,
400→    string? message = null,
401→    long? timestampMillis = null,
402→    CancellationToken cancellationToken = default) =>
403→    ChangeAsync(mutation, message, timestampMillis, cancellationToken).GetAwaiter().GetResult();
