405→  public async ValueTask<DocLocalChange<T>?> ChangeAsync(
406→    Action<AutomergeDocument> mutation,
407→    string? message = null,
408→    long? timestampMillis = null,
409→    CancellationToken cancellationToken = default)
410→  {
411→    ArgumentNullException.ThrowIfNull(mutation);
412→
413→    // Check if we need to initialize the document (virtual document pattern)
414→    AutomergeDocument document;
415→    var existingDoc = Volatile.Read(ref _document);
416→    if(existingDoc is null)
417→    {
418→      // Document doesn't exist yet - create it (handles the case where Find() timed out)
419→      lock(_stateGate)
420→      {
421→        if(_state == HandleState.Loading || _state == HandleState.Requesting)
422→        {
423→          var newDoc = AutomergeDocument.Create();
424→          Initialize(newDoc, isNewDocument: true);
425→          DoneLoading();
426→        }
427→      }
428→      document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
429→    }
430→    else
431→    {
432→      document = existingDoc;
433→    }
434→
435→    EnsureEditable();
436→
437→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
438→    try
439→    {
440→      EnsureEditable();
441→      mutation(document);
442→      var changeHash = document.Commit(message, timestampMillis);
443→      UpdateCachedHeads(document.GetHeads());
444→
445→      if(changeHash is null)
446→      {
447→        return null;
448→      }
449→
450→      var lastChange = document.GetLastLocalChange();
451→      if(lastChange is null)
452→      {
453→        return null;
454→      }
455→
456→      var clonedChange = lastChange.ToArray();
457→      _pendingLocalChanges.Add(clonedChange);
458→      var readOnlyChange = new ReadOnlyCollection<byte[]>([clonedChange]);
459→      var change = new DocLocalChange<T>(this, changeHash, readOnlyChange);
460→      OnChanged(change, isLocal: true, null);
461→      return change;
462→    }
463→    finally
464→    {
465→      _documentLock.Release();
466→    }
467→  }
