469→  /// <summary>
470→  /// Makes a change to the document as if it were at the specified heads, creating a concurrent branch.
471→  /// </summary>
472→  /// <param name="heads">The heads to fork at before making the change.</param>
473→  /// <param name="mutation">The mutation to apply to the forked document.</param>
474→  /// <returns>
475→  /// A list of binary changes representing the concurrent change that was made.
476→  /// </returns>
477→  /// <remarks>
478→  /// <para>
479→  /// This method creates a fork of the document at the specified heads, applies the mutation,
480→  /// commits the change, and then merges the forked document back into the main document.
481→  /// This creates a concurrent branch in the document history.
482→  /// </para>
483→  /// <para>
484→  /// This is useful for reconciling external state that was modified independently from the document.
485→  /// For example, if you have a text editor that was modified while disconnected from the document,
486→  /// you can use ChangeAt to apply those changes as if they happened at the point when the editor
487→  /// last synced.
488→  /// </para>
489→  /// </remarks>
490→  /// <exception cref="ArgumentNullException">Thrown when heads or mutation is null.</exception>
491→  /// <exception cref="ArgumentException">Thrown when heads is empty.</exception>
492→  /// <exception cref="InvalidOperationException">Thrown when the document is not ready or is read-only.</exception>
493→  public IReadOnlyList<byte[]> ChangeAt(
494→    IReadOnlyList<string> heads,
495→    Action<AutomergeDocument> mutation)
496→  {
497→    if(heads is null)
498→    {
499→      throw new ArgumentNullException(nameof(heads));
500→    }
501→
502→    if(heads.Count == 0)
503→    {
504→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
505→    }
506→
507→    ArgumentNullException.ThrowIfNull(mutation);
508→    EnsureEditable();
509→
510→    return ChangeAtAsync(heads, mutation, CancellationToken.None).GetAwaiter().GetResult();
511→  }
512→
513→  async ValueTask<IReadOnlyList<byte[]>> ChangeAtAsync(
514→    IReadOnlyList<string> heads,
515→    Action<AutomergeDocument> mutation,
516→    CancellationToken cancellationToken)
517→  {
518→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
519→
520→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
521→    try
522→    {
523→      EnsureEditable();
524→
525→      // Fork the document at the specified heads
526→      using var forkedDoc = document.ForkAtHeads(heads);
527→
528→      // Apply the mutation to the forked document
529→      mutation(forkedDoc);
530→
531→      // Commit the changes in the forked document
532→      var changeHash = forkedDoc.Commit();
533→      if(changeHash is null)
534→      {
535→        // No changes were made, return empty
536→        return Array.Empty<byte[]>();
537→      }
538→
539→      // Get the change bytes from the forked document
540→      var lastChange = forkedDoc.GetLastLocalChange();
541→      if(lastChange is null)
542→      {
543→        return Array.Empty<byte[]>();
544→      }
545→
546→      // Merge the forked document back into the main document
547→      var mergedHashes = document.Merge(forkedDoc);
548→
549→      // Update cached heads
550→      UpdateCachedHeads(document.GetHeads());
551→
552→      // Emit change event
553→      var changeBytes = lastChange.ToArray();
554→      OnChanged(null, isLocal: true, new[] { changeBytes });
555→
556→      // Return the change as a single-item list
557→      return new ReadOnlyCollection<byte[]>(new[] { changeBytes });
558→    }
559→    finally
560→    {
561→      _documentLock.Release();
562→    }
563→  }
564→
565→  public async ValueTask ApplyRemoteChangesAsync(
566→    IEnumerable<byte[]> changes,
567→    CancellationToken cancellationToken = default)
568→  {
569→    ArgumentNullException.ThrowIfNull(changes);
570→    EnsureReady();
571→
572→    var changeBatch = changes.Select(change => change.ToArray()).ToArray();
573→    if(changeBatch.Length == 0)
574→    {
575→      return;
576→    }
577→
578→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
579→
580→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
581→    try
582→    {
583→      document.ApplyChanges(changeBatch);
584→      UpdateCachedHeads(document.GetHeads());
585→      OnChanged(null, isLocal: false, changeBatch);
586→    }
587→    finally
588→    {
589→      _documentLock.Release();
590→    }
591→  }
