609→  public void Merge(DocHandle<T> other)
610→  {
611→    if(other is null)
612→    {
613→      throw new ArgumentNullException(nameof(other));
614→    }
615→
616→    EnsureEditable();
617→
618→    using var mergeLock = new CompositeSemaphore(_documentLock, other._documentLock);
619→
620→    var doc = DocInternal();
621→    var otherDoc = other.DocInternal();
622→
623→    var hashes = doc.Merge(otherDoc);
624→    if(hashes.Count > 0)
625→    {
626→      UpdateCachedHeads(doc.GetHeads());
627→      OnChanged(null, isLocal: true, null);
628→    }
629→  }
