631→  public IReadOnlyList<byte[]> DrainLocalChanges()
632→  {
633→    EnsureReady();
634→
635→    lock(_stateGate)
636→    {
637→      if(_pendingLocalChanges.Count == 0)
638→      {
639→        return Array.Empty<byte[]>();
640→      }
641→
642→      var drained = _pendingLocalChanges
643→        .Select(change => change.ToArray())
644→        .ToArray();
645→
646→      _pendingLocalChanges.Clear();
647→      return new ReadOnlyCollection<byte[]>(drained);
648→    }
649→  }
