110→    using var doc = AutomergeDocument.Create();
111→
112→    doc.PutString(doc.RootId, "initial", "value");
113→    doc.Commit();
114→    var baseHeads = doc.GetHeads();
115→
116→    doc.PutString(doc.RootId, "main", "change");
117→    doc.Commit();
118→
119→    // Act - Fork at base heads (this creates an independent copy)
120→    using var forked = doc.ForkAtHeads(baseHeads);
121→
122→    // Make concurrent changes
123→    forked.PutString(forked.RootId, "forked", "change");
124→    forked.Commit();
125→
126→    // Assert
127→    // NOTE: Due to FFI wrapper limitations, ForkAtHeads currently uses Clone + Isolate,
128→    // which creates a full clone. The key behavior for ChangeAt is that we can make
129→    // concurrent changes independently and merge them back.
130→    var forkedJson = forked.HydrateJson();
131→    var currentJson = doc.HydrateJson();
