135→    Assert.Contains("\"initial\":\"value\"", currentJson);
136→
137→    // The forked document should have the concurrent change
138→    Assert.Contains("\"forked\":\"change\"", forkedJson);
139→
140→    // The main document should have its change
141→    Assert.Contains("\"main\":\"change\"", currentJson);
142→
143→    // Key test: changes to forked doc don't affect original
144→    Assert.DoesNotContain("\"forked\":\"change\"", currentJson);
