816→  [Fact]
817→  public void AllNewApis_CombinedInOneDocument_ShouldNotThrow()
818→  {
819→    using var doc = AutomergeDocument.Create();
820→    var root = doc.RootId;
821→
822→    // Sprint 2: Counter + Text + Fork + EmptyChange + BaseHeads
823→    doc.PutCounter(root, "counter", 0);
824→    doc.Increment(root, "counter", 10);
825→    var textId = doc.PutObject(root, "text", AutomergeContainerType.Text);
826→    doc.SpliceText(textId, 0, 0, "Hello World");
827→    doc.Commit("sprint2 setup");
828→
829→    var text = doc.GetText(textId);
830→    Assert.Equal("Hello World", text);
831→    var baseHeads = doc.BaseHeads();
832→    Assert.NotEmpty(baseHeads);
833→
834→    // Sprint 3: List gets, Map get object, GetAll
835→    var list = doc.PutObject(root, "list", AutomergeContainerType.List);
836→    doc.ListInsertString(list, 0, "item0");
837→    var nestedMap = doc.PutObject(root, "nested", AutomergeContainerType.Map);
838→    doc.PutString(nestedMap, "inner", "val");
839→    doc.Commit("sprint3 setup");
840→
841→    Assert.Equal("item0", doc.ListGetString(list, 0));
842→    Assert.NotNull(doc.GetObject(root, "nested"));
843→    var all = doc.GetAll(root, "counter");
844→    Assert.NotEmpty(all);
845→
846→    // Sprint 4: Mark + Unmark
847→    doc.Mark(textId, 0, 5, "bold", true);
848→    doc.Mark(textId, 6, 11, "link", "https://example.com");
849→    doc.Commit("sprint4 marks");
850→
851→    // Sprint 5: GetMarks + GetSpans
852→    var marks = doc.GetMarks(textId);
853→    Assert.Equal(2, marks.Count);
854→    var spans = doc.GetSpans(textId);
855→    Assert.NotEmpty(spans);
856→
857→    // Sprint 6: SplitBlock
858→    var textId2 = doc.PutObject(root, "richtext", AutomergeContainerType.Text);
859→    doc.SpliceText(textId2, 0, 0, "Part one.Part two.");
860→    doc.SplitBlock(textId2, 9);
861→    doc.Commit("sprint6 blocks");
862→
863→    // Sprint 7: ListSplice + ListPut + Cursor
864→    doc.ListInsertString(list, 1, "item1");
865→    doc.ListPutString(list, 0, "replaced");
866→    doc.Commit("sprint7 list mutation");
867→
868→    var cursor = doc.GetCursor(list, 0);
869→    var pos = doc.GetCursorPosition(list, cursor);
870→    Assert.Equal(0UL, pos);
871→
872→    // Sprint 8: Keys/Length at heads, Values, Range, Parents, PathToObject
873→    var heads = doc.GetHeads();
874→    doc.GetKeysAtHeads(root, heads);
875→    doc.LengthAtHeads(list, heads);
876→    doc.Values(root);
877→    doc.MapRangeFull(root);
878→    doc.ListRangeFull(list);
879→    var path = doc.PathToObject(nestedMap);
880→    Assert.NotEmpty(path);
881→
882→    // Sprint 9: Save/Load variants, DiffIncremental, etc.
883→    var saved = doc.SaveNoCompress();
884→    var savedWithOpts = doc.SaveWithOptions(new SaveOptions { Deflate = false });
885→    Assert.NotEmpty(saved);
886→    Assert.NotEmpty(savedWithOpts);
887→
888→    var diffPatches = doc.DiffIncremental();
889→    // Note: may be empty if no changes since last diff call
890→
891→    var emptyHash = doc.EmptyChange("verification marker");
892→    Assert.NotEmpty(emptyHash);
893→
894→    using var forked = doc.Fork();
895→    Assert.Equal(doc.GetText(textId), forked.GetText(textId));
896→
897→    // Bundle
898→    var bundleHeads = doc.GetHeads();
899→    var bundle = doc.Bundle(bundleHeads);
900→    Assert.NotEmpty(bundle);
901→
902→    // GetMissingDeps + HasOurChanges
903→    var missing = doc.GetMissingDeps(bundleHeads);
904→    Assert.Empty(missing);
905→
906→    using var syncState = doc.CreateSyncState();
907→    doc.HasOurChanges(syncState);
908→
909→    // Final: verify the document is fully valid by save/load roundtrip
910→    var finalSave = doc.Save();
911→    using var reloaded = AutomergeDocument.Load(finalSave);
912→    Assert.Equal(doc.GetText(textId), reloaded.GetText(textId));
913→    Assert.Equal(doc.GetString(nestedMap, "inner"), reloaded.GetString(nestedMap, "inner"));
914→  }
