320→  public async Task InitializeAsync()
321→  {
322→    // CRITICAL: Wait before initializing to ensure previous test's Rust FFI state is fully cleaned
323→    await Task.Delay(3000);
324→
325→    var cancellationToken = new CancellationTokenSource(TimeSpan.FromSeconds(30)).Token;
326→
327→    var appHost = await DistributedApplicationTestingBuilder.CreateAsync<Ray_Tests_AppHost>(
328→      args: ["DcpPublisher:RandomizePorts=false"],
329→      cancellationToken: cancellationToken);
330→
331→    appHost.Services.AddLogging(logging =>
332→    {
333→      logging.SetMinimumLevel(LogLevel.Debug);
334→      logging.AddFilter(appHost.Environment.ApplicationName, LogLevel.Debug);
335→      logging.AddFilter("Aspire.", LogLevel.Debug);
336→    });
337→
338→    appHost.Services.ConfigureHttpClientDefaults(clientBuilder =>
339→    {
340→      clientBuilder.AddStandardResilienceHandler();
341→    });
342→
343→    _app = await appHost.BuildAsync(cancellationToken);
344→    await _app.StartAsync(cancellationToken);
345→
346→    // Wait for SignalR hub to be healthy
347→    await _app.ResourceNotifications
348→      .WaitForResourceHealthyAsync("signalr-hub", cancellationToken);
349→
350→    // Get the hub URL
351→    var resourceModel = _app.Services.GetRequiredService<DistributedApplicationModel>();
352→    var signalRResource = resourceModel.Resources.Single(r => r.Name == "signalr-hub");
353→    var httpEndpoint = signalRResource.Annotations.OfType<EndpointAnnotation>()
354→      .First(e => e.Name == "http");
355→    var allocatedEndpoint = httpEndpoint.AllocatedEndpoint
356→      ?? throw new InvalidOperationException("HTTP endpoint was not allocated");
357→
358→    _hubUrl = $"{allocatedEndpoint.UriString}/hubs/documents";
359→  }
