361→  /// <summary>
362→  /// Creates a Repo with in-memory storage and SignalR network adapter.
363→  /// </summary>
364→  async Task<Ray.Automerge.Repository.Repo> CreateRepoAsync(string peerName)
365→  {
366→    var loggerFactory = LoggerFactory.Create(builder =>
367→    {
368→      builder.AddConsole();
369→      builder.SetMinimumLevel(LogLevel.Debug);
370→      builder.AddFilter("Ray.Automerge", LogLevel.Debug);
371→    });
372→
373→    // Create SignalR connection service
374→    var connectionService = TestConnectionServiceFactory.Create(_hubUrl);
375→    _connectionServices.Add(connectionService);
376→
377→    // Create SignalR network adapter
378→    var adapter = new SignalRNetworkAdapter(connectionService, loggerFactory);
379→    _adapters.Add(adapter);
380→
381→    // Connect the adapter and wait for it to be ready
382→    var peerId = PeerId.Generate();
383→    adapter.Connect(peerId, null);
384→    await adapter.WhenReady().WaitAsync(TimeSpan.FromSeconds(5));
385→
386→    // Create repo with in-memory storage
387→    var repo = new Ray.Automerge.Repository.Repo(new RepoConfig
388→    {
389→      PeerId = peerId,
390→      Storage = new InMemoryStorageAdapter(),
391→      NetworkAdapters = [adapter],
392→      IsEphemeral = false
393→    });
394→
395→    _repos.Add(repo);
396→
397→    return repo;
398→  }
