400→  public async Task DisposeAsync()
401→  {
402→    // Dispose repos first
403→    foreach (var repo in _repos)
404→    {
405→      try { repo.Dispose(); }
406→      catch { /* Ignore disposal errors */ }
407→    }
408→    _repos.Clear();
409→
410→    // Dispose adapters
411→    foreach (var adapter in _adapters)
412→    {
413→      try { await adapter.DisposeAsync(); }
414→      catch { /* Ignore disposal errors */ }
415→    }
416→    _adapters.Clear();
417→
418→    // Dispose connection services
419→    foreach (var connectionService in _connectionServices)
420→    {
421→      try { await connectionService.DisposeAsync(); }
422→      catch { /* Ignore disposal errors */ }
423→    }
424→    _connectionServices.Clear();
425→
426→    // Dispose the entire app infrastructure (SignalR hub, etc.)
427→    if (_app is not null)
428→    {
429→      await _app.DisposeAsync();
430→      _app = null;
431→    }
432→
433→    // CRITICAL: Force garbage collection to finalize all native resources
434→    // This ensures all AutomergeDocument instances are properly disposed before the next test.
435→    // The Rust FFI layer (automerge-0.7.0) has a known issue where actor removal during cleanup
436→    // panics if there are lingering uncommitted transactions in the Rust heap.
437→    GC.Collect();
438→    GC.WaitForPendingFinalizers();
439→
440→    // CRITICAL: Wait for the automerge Rust FFI library to fully cleanup
441→    // Without this delay, the next test may crash due to lingering state in the native library
442→    // Increased to 5 seconds due to persistent threading issues in the Rust FFI
443→    await Task.Delay(5000);
444→  }
445→}
